#include <stdio.h>
int is_prime(long long n) {
    if (n < 2) return 0;
    if (n == 2 || n == 3) return 1;
    if (n % 2 == 0 || n % 3 == 0) return 0;
    for (long long i = 5; i * i <= n; i += 6)
        if (n % i == 0 || n % (i + 2) == 0) return 0;
    return 1;
}
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    long long pref = 0, x; int count = 0;
    for (int i = 0; i < n; i++) {
        scanf("%lld", &x);
        pref += x;
        if (is_prime(pref)) count++;
    }
    printf("%d\n", count);
    return 0;
}

