    const n = parseInt(toks[0], 10);
    let pref = 0, count = 0;
    for (let i = 1; i <= n; i++) {
        pref += parseInt(toks[i], 10);
        if (isPrime(pref)) count++;
    }
    console.log(count);
}
main();

